    d.codigo_estudiante &&
    d.nombre_estudiante &&
    d.programa_academico &&
    d.periodo_academico &&
    d.curso
  );

  const dniValido = /^\d{8}$/.test(String(d.dni || ''));

  d.campos_validos = camposCompletos;
