return items.map(item => {
  const dni = String(item.json.dni || '');

  // Protección demostrativa compatible con el Code node de n8n.
  // No utiliza módulos externos.
  let hash = 2166136261;
  for (let i = 0; i < dni.length; i++) {
    hash ^= dni.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }

  item.json.dni_hash =
    'PROT-' + (hash >>> 0).toString(16).padStart(8, '0').toUpperCase();

  // Evitamos que el DNI original continúe por el workflow.
  delete item.json.dni;

  item.json.control_proteccion_dato = true;

  return item;
});

return items.map(item => {

  const texto = `${item.json.nombre_estudiante || ''} ${item.json.programa_academico || ''} ${item.json.curso || ''}`.toLowerCase();

  const patrones = [
    '<script',
    'drop table',
    'select * from',
    'union select',
    '--',
    '../',
    'or 1=1',
    'admin',
    'root'
  ];

  const coincidencias = patrones.filter(p => texto.includes(p));

  item.json.patrones_sospechosos = coincidencias;
  item.json.contenido_sospechoso = coincidencias.length > 0;
  item.json.control_filtrado = true;

  return item;
});

return items.map(item => {

  item.json.prompt_groq = `Actúa como analista de ciberseguridad.

Analiza el siguiente registro de matrícula y clasifícalo como legitimo o registro_anomalo.

